import { daysBetween } from './dates.js';
import { balanceDue } from './payments.js';
import { lineTotal, lineDiscount, lineVat } from './invoices.js';

/**
 * Get overdue invoices as of a given date.
 * Returns invoices with status 'issued' or 'partially_paid' whose dueDate is before asOf,
 * sorted by most overdue first.
 * @param {Array} invoices - Array of invoice objects
 * @param {string} asOf - Reference date in YYYY-MM-DD format
 * @returns {Array} - Array of { number, customerId, dueDate, daysOverdue, due }
 */
export function overdueInvoices(invoices, asOf) {
  const overdue = [];

  for (const invoice of invoices) {
    if ((invoice.status === 'issued' || invoice.status === 'partially_paid') &&
        invoice.dueDate < asOf) {
      const daysOverdue = daysBetween(invoice.dueDate, asOf);
      overdue.push({
        number: invoice.number,
        customerId: invoice.customerId,
        dueDate: invoice.dueDate,
        daysOverdue,
        due: balanceDue(invoice),
      });
    }
  }

  overdue.sort((a, b) => b.daysOverdue - a.daysOverdue);
  return overdue;
}

/**
 * Get a VAT summary over invoices with status 'issued', 'partially_paid', or 'paid'.
 * Returns one entry per VAT rate with aggregated base and VAT amounts.
 * Sorted by rate from high to low.
 * @param {Array} invoices - Array of invoice objects
 * @returns {Array} - Array of { rate, base, vat }
 */
export function vatSummary(invoices) {
  const vatMap = new Map();

  for (const invoice of invoices) {
    if (invoice.status === 'issued' || invoice.status === 'partially_paid' || invoice.status === 'paid') {
      for (const line of invoice.lines) {
        const rate = line.vatRate ?? 0;
        const base = lineTotal(line) - lineDiscount(line);
        const vat = lineVat(line);

        if (!vatMap.has(rate)) {
          vatMap.set(rate, { rate, base: 0, vat: 0 });
        }
        const entry = vatMap.get(rate);
        entry.base += base;
        entry.vat += vat;
      }
    }
  }

  const result = Array.from(vatMap.values());
  result.sort((a, b) => b.rate - a.rate);
  return result;
}

/**
 * Calculate late fee for an invoice.
 * 0.04% of the amount still due for every day the invoice is overdue.
 * Returns 0 if the invoice is not overdue.
 * @param {Object} invoice - Invoice object with dueDate and lines
 * @param {string} asOf - Reference date in YYYY-MM-DD format
 * @returns {number} - Late fee in cents, rounded to nearest cent
 */
export function lateFee(invoice, asOf) {
  if (invoice.dueDate >= asOf) {
    return 0;
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  const amountDue = balanceDue(invoice);
  const fee = amountDue * daysOverdue * 0.0004;
  return Math.round(fee);
}

