test('lateFee with complex invoice', () => {
  const invoice = {
    dueDate: '2026-08-07',
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 20, vatRate: 21 },
      { qty: 5, unitPrice: 8000, discountPercent: 10, vatRate: 9 },
    ],
    payments: [{ amount: 50000, date: '2026-09-01' }],
  };
  const fee = lateFee(invoice, '2026-10-07');
  const daysOverdue = 61;

  // Calculate expected balance due
  const line1Total = 10 * 10000;
  const line1Discount = Math.round(line1Total * 20 / 100);
  const line1Base = line1Total - line1Discount;
  const line1Vat = Math.round(line1Base * 21 / 100);

  const line2Total = 5 * 8000;
  const line2Discount = Math.round(line2Total * 10 / 100);
  const line2Base = line2Total - line2Discount;
  const line2Vat = Math.round(line2Base * 9 / 100);

  const totalDue = line1Total - line1Discount + line1Vat + line2Total - line2Discount + line2Vat;
  const balanceDue = totalDue - 50000;

  const expectedFee = Math.round(balanceDue * daysOverdue * 0.0004);
  assert.equal(fee, expectedFee);
});

