  const fee = lateFee(invoice, '2026-10-07');
  const daysOverdue = 101;
  const expectedFee = Math.round(25000 * daysOverdue * 0.0004);
  assert.equal(fee, expectedFee);
  assert.equal(fee, 1010);
});

